INSERT INTO `tbl_conocimientos` (`ID_CONOCIMIENTO`, `DESCRIPCION_CONOCIMIENTO`, `ELEMENTO_CONOCIMIENTO`) VALUES
(1, '01. Manual de procedimiento para la inspección y encendido de la excavadora (a,i). 02. Tipos, características y especificaciones técnicas de aceites, lubricantes, combustibles y filtros. 03. Características, funcionamiento y partes de los: controles, motor, sistemas de dirección, frenos, sistemas de lubricación, sistema hidráuilico, sistema de transmisión, tren de rodaje, sistema eléctrico y de refrigeración (c,d,e). 04. Procedimientos de comprobación de funcionamiento de los componentes, controles y sistemas mecánicos de la excavadora (d). 05. Diágnistico e interpretación de las alarmas, fallas e indicaciones de los controles de la excavadora (d,e). 06. Interpretación de simbología y diagramas mecánicos y eléctricos de la excavadora (g,h). 07. Instrumentos o listas de chequeo utilizadas para el registro de la inspección de la excavadora (f). 08. Actividades y procedimientos para el mantenimiento preventivo establecido para la excavadora (g). 09. Objeto, propósito, frecuencia y variables criticas de la inspección de la excavadora (h). 10. Unidades de medida de: peso, velocidad, presiones, potencia, eléctricas y de temperatura (G). 11. Reglamentación específica de seguridad e higiene para la inspección de la pala excavadora (e,h,i)', 5),
(2, '01. Manual de procedimientos y técnicas de operación de la excavadora (a,c,d). 02. Conceptos básicos estándares de producción, ciclos de trabajo y rendimientos de la pala excavadora en diferentes áreas y tipos de material a cargar (C,f). 03. Definición de los frentes de trabajo, nomenclatura, tipos de terrenos y pendientes, tipo de material para cargue, ángulos de taludes (c,g). 04. Técnicas de nivelación de terrenos y construcción de terraplenes (c,g). 05. Características básicas, funcionamiento y componentes de los sistemas hidráulico, eléctricos, de enfriamiento, de lubricación, de frenos, de combustible, filtros y de tren de potencia de la excavadora (h,i). 06. Procedimientos de comprobación diágnostico y fallas de las condiciones de los mandos, alarmas y sistemas componentes de la excavadora (i). 07. Sistemas de emergencia estándar y optativos de la excavadora (i,k). 08. Técnicas de disposición y volúmenes de cargue del material en los diferentes tipos de medios de transporte. 09. Técnicas de posicionamiento de la excavadora en la operación (b,c,d). 10. Reglamentación específica de seguridad e higiene para la operación de la excavadora (j,k).', 6),
(12, '01. Características, Tipos y Aplicaciones de Formatos de Talle . (T, U, V). 02. Características y Tipos de Manuales Técnicos de Automotores. (Todos Los Criterios) 03. Características, Tipos y Aplicaciones de Instrumentos, Herramientas y Equipos utilizados en Mantenimiento Rutinario. (A, B, D, E, F, G, H, I, J, K, L, N, O, P, Q, R, V). 04. Características y Tipos de Automotores: Livianos, Medianos, Pesados. (Todos los Criterios). 05. Características, Tipos y Aplicaciones de Lubricantes, Líquidos Refrigerantes, Líquidos Para Frenos y Combustibles (A, B, D, E, F, H, J). 06. Sistemas de los Automotores, Función y Componentes: Motor  (Alimentación, Encendido, Arranque, Carga, Lubricación y Refrigeración). (A, B, C, D, F, I, J, N, O, P, Q, R, T). 07. Características, Funcionamiento y Técnicas de Desmontaje y Montaje de los Componentes de los Sistemas del Moto  (Todos los criterios) Alimentación de Combustible, Lubricación, Refrigeración, Admisión de Aire y Escape de Gases Distribución Mecánica Arranque Encendido, Carga. 08. Características y Funcionamiento de Componentes de los Circuitos Hidráulicos y Neumáticos Básicos del Automotor . (A, B, C, D, F, H, J, M, Q, R, S). 09. Electricidad Básica: (A,B,O,P,R,S). Conceptos y Unidades de Voltaje, Intensidad de Corriente, Resistencia Eléctrica, Potencia. Instrumentos de Medición (Multimerol). Baterías, Tipos y Mantenimiento. Circuitos en Serie, Paralelos y Mixtos. Características y Tipos de Bombillos para Automotores. Clasificación e Identificación de Cables, Conecto es, Te minales y Fusibles. 10. Técnicas y Procedimientos de Cambio de Lubricantes de: Moto  (A,B,D,F,J). Sistema de Transmisión de Potencia (A,B,D,J) Seguridad y Rodaje (A, B, G, H, K, L, M) Dirección (A, B, D, E). 11. Características, Tipos y Técnicas de cambio de Refrigeantes para Moto  y Ai e Acondicionado (A, B, D). 12. Características y Tipos de Llantas. (A, B, K, L, M). 13. No mas Ambientales, de Higiene y de Seguridad Industrial. (Todos los criterios).