(5, 199, '01', 'Inspeccionar la excavadora y procedimientos establecidos por el fabricante'),
(6, 199, '02', 'Operar la excavadora de acuerdo a la orden de trabajo'),
(7, 344, '01', 'Inspeccionar el estado de vehículos automotores, de acuerdo con procedimientos y normatividad vigente.'),
(10, 360, '01 ', 'Diagnosticar los sistemas del motor diesel cumpliendo las normas ambientales, de salud ocupacional y especificaciones técnicas del fabricante '),
(11, 344, '02', 'Ejecutar rutinas de mantenimiento en vehículos automotores, de acuerdo con procedimientos técnicos y normatividad vigente. '),
(13, 352, 'elem', 'elemento prueba'),
(14, 360, '02', 'Reparar fallas y averías de los motores diesel, cumpliendo las normas ambientales, de salud ocupacional y especificaciones técnicas del fabricante. '),
(15, 345, '01', 'Diagnosticar el sistema de alimentación e inyectores de combustible del motor diesel cumpliendo las normas ambientales, de salud ocupacional y especificaciones técnicas del fabricante.'),
(16, 345, '02', 'Reparar fallas del sistema de alimentación e inyectores de combustible , cumpliendo las normas ambientales, de seguridad y especificaciones técnicas del fabricante.'),
(17, 357, '01', 'Operar recursos tecnológicos teniendo en cuenta los procesos y procedimientos establecidos por la organización y los estándares de calidad.'),
(18, 357, '02', 'Controlar recursos y herramientas tecnológicas para el procesamiento de la información de la unidad administrativa de acuerdo con las políticas de la organización.'),
(19, 528, '01', 'Recibir documentos de acuerdo con normas vigentes.'),
(20, 528, '02', 'Despachar documentos teniendo en cuenta la normatividad vigente y políticas de la organización.'),
(21, 528, '03', 'Archivar documentos de acuerdo con la normatividad vigente.'),
(22, 528, '04', 'Proveer información de acuerdo con normatividad y políticas organizacionales.'),
(23, 256, '01', 'Ofrecer atención personalizada a los clientes de acuerdo con las políticas de la organización.'),
(24, 256, '02', 'Atender a los clientes utilizando las tecnologías de acuerdo con el protocolo de la organización.'),
(25, 358, '01', 'Registrar las operaciones del ejercicio en los documentos correspondientes de acuerdo con los procedimientos organizacionales, normas y legislación vigentes.'),
(26, 358, '02', 'Elaborar los estados financieros de acuerdo con los procedimientos organizacionales, normas y legislación vigentes.'),
(27, 358, '03', 'Analizar las transacciones comerciales y los estados financieros de la empresa teniendo en cuenta los resultados obtenidos y las políticas organizacionales.'),
(28, 289, '01', 'Mantener ambientes de trabajo seguros y saludables, según reglamentación institucional y normativa legal vigente.'),
(30, 289, '02', 'Ejecutar prácticas de trabajo seguras y saludables, según reglamentación institucional y normativa legal vigente'),
(31, 301, '01', 'Realizar programas de sensibilización, capacitación y actualización relacionados con la protección de la salud y el bienestar de los trabajadores.'),
(32, 301, '02', 'Verificar cumplimiento de cobertura en términos de promoción y prevención de acuerdo con indicadores y metas establecidas.'),
(33, 321, '01', 'Evaluar el riesgo en función de la amenaza y la vulnerabilidad con proyección a escenarios de afectación.'),
(34, 321, '02', 'Intervenir la condición de amenaza y vulnerabilidad mediante estrategias intersectoriales.'),
(35, 321, '03', 'Fortalecer la capacidad de planeamiento y respuesta en relación con escenarios de afectación y nivel de intervención.'),
(36, 375, '01', 'Redactar los documentos, de acuerdo con las normas vigentes'),
(37, 375, '02', 'Digitar los documentos, de acuerdo con su tipo y normas establecidas.'),
(38, 375, '03', 'Transcribir los documentos, de acuerdo con las normas vigentes.'),
(39, 385, '01', 'Verificar las entradas y salidas de los objetos, de acuerdo con los procedimientos establecidos.'),
(40, 385, '02', 'Realizar devoluciones de los objetos según los procedimientos establecidos.'),
(41, 385, '03', 'Alistar los objetos según los procedimientos establecidos y solicitud de pedido.'),
(42, 398, '01', 'Empacar los objetos de acuerdo con su naturaleza y estándares establecidos.'),
(43, 398, '02', 'Embalar la carga de acuerdo con la naturaleza, normatividad de embalajes, ordenes de alistamiento y modos de transporte.'),
(44, 398, '03', 'Marcar los objetos y la carga según sus características, especificaciones señaladas por la organización y normas internacionales.'),
(45, 431, '01', 'Informar a las personas acerca de los servicios de salud disponibles en su localidad.'),
(46, 431, '02', 'Aplicar cuidados de primer respondiente a las personas de acuerdo con el evento y normativa vigente.'),
(47, 446, '01', 'Contribuir a la gestión de acciones de salud integral para niños y niñas hasta los 6 años y para las familias gestantes, de acuerdo con planes de desarrollo nacionales, regionales y locales.'),
(48, 446, '02', 'Brindar atención básica de acuerdo con los factores de riesgo identificados, según lineamientos de salud vigentes'),
(49, 446, '03', 'Desarrollar acciones de promoción de la salud, nutrición, entornos y practicas de vida saludable, enmarcadas en las estrategias de salud integral dirigidas a la primera infancia'),
(50, 451, '01', 'Implementar estrategias de acompañamiento pedagógico para favorecer el desarrollo integral de niños y niñas hasta los 6 años de edad en el marco de las competencias para la primera infancia'),
(51, 451, '02', 'Utilizar estrategias lúdicas y de lenguajes expresivos para promover el desarrollo de competencias en niños y niñas, de acuerdo con las diferentes modalidades de atención y dimensiones del desarrollo'),
(52, 460, '01', 'Desarrollar estrategias de sensibilización y formación para niños, niñas, familia y comunidad, en los derechos y responsabilidades de la primera infancia'),
(53, 460, '02', 'Canalizar y hacer seguimiento a las situaciones de vulneración de derechos para la restitución de los mismos de acuerdo a la coresponsabilidad de los diferentes actores'),
(54, 471, '01', 'Propiciar la participación de los niños y las niñas en los diferentes ambientes de desarrollo, desde los contextos particulares'),
(55, 471, '02', 'Orientar a la familia y la comunidad en la implementación de estrategias para promover la participación infantil, según lineamientos técnicos para garantizar los derechos y deberes de la primera infancia.'),
(56, 477, '01', 'Mantener ambientes de trabajos seguros y saludables, según reglamentación institucional y normativa legal vigente'),
(57, 477, '02', ' Ejecutar prácticas de trabajo seguras y saludables, según reglamentación institucional y normativa legal vigente.'),
