INSERT INTO `tbl_evidencias` (`ID_EVIDENCIA`, `DESCRIPCION_EVIDENCIA`, `ELEMENTO_EVIDENCIA`) VALUES
(1, 'DESEMPEÑO: 1. Observación del candidato en los procedimientos utilizados en la inspección del equipo, de acuerdo con las categorías del rango (d,e,f,h,i,j) inspección de los componentes de la excavadora, inspección de los sistemas de la excavadora, inspección de los controles. 2. Observación de los procedimientos de seguridad utilizados en la inspección de la excavadora (e,h,i). CONOCIMIENTO: 1. Prueba oral o escrita de los conocimientos y comprensión (2,3,5,11) especificados para el desempeño. PRODUCTO: 1. Condición de funcionamiento de la excavadora inspeccionada y estado cubriendo las categorías y clases del rango: (c,f,i) componentes de la excavadora, sistemas mecánicos de la excavadora, controles la retroexcavadora inspeccionada. 2. Reporte o lista de chequeo diligenciadas por el candidato con la condición, fallas y actividades realizadas en la inspección de la excavadora (f,g). 3. Niveles de los fluidos de la excavadora (b). 4. Posicionamiento del equipo para la inspección (a).', 5),
(2, 'DESEMPEÑO: 1. Observación de los procedimientos de operación de la excavadora en: (c,d,e,h) cargue de camiones en frentes de explotación, en el apilamiento de material, en la excavación o elaboración de zanjas, en la conformación de vías o accesos y terraplenes. 2. Observación del desplazamiento de la excavadora en terrenos planos y en terrenos con pendiente (a,c). 3. Observación de los procedimientos y normatividad de seguridad utilizados en la operación de la excavadora (i,j,k). CONOCIMIENTO: 1. Prueba escrita u oral sobre los conocimientos y comprensión (5,6,10) especificados para el desempeño. PRODUCTO: 1. Características final del frente o área de trabajo respecto a las especificaciones técnicas ordenadas luego de ejecutada la labor de: (b,c,g) cargue de camiones en frentes, cargue de camiones en patios, apilamiento de material, excavaciones o zanjas, conformación de vías o accesos y terraplenes. 2. Rendimiento de la actividad desarrollada de acuerdo al estándar de la actividad realizada, u orden de trabajo (e,f). 3. Reporte entregado con los rendimientos obtenidos, fallas y riesgos encontrados en la operación (f,i,j). 4. Posicionamiento de la excavadora en el momento de realizar cada una de las labores de trabajo (c,d) frentes de explotación, terrenos planos, terrenos con pendiente.', 6),
(4, 'CONOCIMIENTO 1. Evaluación Oral o Escrita sobre: Tipos de Mantenimientos, Procedimientos de Inspección Tipos y Componentes de los Sistemas del Vehículo DESEMPEÑO 1. Resultado de la inspección del Equipo de Transporte Liviano, Mediano y Pesado. PRODUCTO 1. Una (1) Lista de Chequeo de Inspección Diligenciada para Vehículos: Livianos, Medianos y Pesados ', 7),
(6, 'CONOCIMIENTO 1. Respuesta a Preguntas sobre: - Fundamentos Característica - Ciclos se Funcionamiento sel Motor Diésel o de Motores - Procedimientos de Evaluación y Diagnóstico - Características y Tipos de Motores Diésel - Función de los subsistemas Componentes de los Motores. Conceptos De Electricidad Automotriz Aplicada a Motores Diésel. Tipos y Aplicaciones de Sensores y Actuadores en los Motores Diésel. Procedimientos de Análisis de Fallas de Sensores, Actuadores y Componentes de los Motores Diésel. Conceptos de Combustión y Oxidación. Química de la Combustión. Polución Y Contaminación Ambiental. Características y Función de los equipos Auxiliares de la Sobrealimentación. Características de Equipos e Instrumentos de Diagnóstico de Motores Diésel. Características Físico-Químicas de Lubricantes y refrigerantes. DESEMPEÑO 1. Resultado de una Observación en los Procesos de: Manejo de Equipos e Instrumentos de Diagnóstico en Motores Diésel. Interpretación de Resultados del Diagnóstico del Motor. Diagnóstico de Subsistemas del Motor. Verificación de los Equipos Auxiliares y Periféricos del Motor  PRODUCTO 1. Un (1) Informe de Diagnóstico (Determinación y Evaluación Fallas) del Motor Diésel de Acuerdo con Resultados de Pruebas e Información de Equipos e Instrumentos de Diagnóstico. Un (1) Informe de Análisis de Emisiones de Gases de Motores. ? Un (1) Informe de los Resultados del Análisis de Aceite. ', 10),
(7, 'CONOCIMIENTO 1. Respuesta a preguntas escritas o verbales Sobre: Características de Manuales Técnicos del Motor. Ciclo Termodinámicos y Funcionamiento de Motores Diésel de 2 Y 4 Tiempos).Cámaras de Combustión..Características, Función y Cuidados en los Procesos de Desarmado, Verificación y Armado de los Componentes de los Motores Diésel. Características de los Componentes de los Motores Diésel. Conceptos de Diagramas de Fase Fe-C, Esfuerzo de formacion y Resistencia de Materiales. Conceptos de Tratamientos Térmicos.Conceptos de Metrología. Características de Instrumentos de Metrología. Conceptos de Ajustes y Tolerancias Normas de Salud Ocupacional y Ambiental Aplicada a Talleres de Mantenimiento Automotriz - Criterios de Reutilización de Componentes. DESEMPEÑO 1. Un Resultado de la Observación en el Proceso de Verificación Dimensional de Componentes del Motor utilizando Instrumentos. Resultado de una Observación en la Aplicación de los Procesos de Reutilización o Cambio de los Componentes de los Motores. Resultado de una Observación del Proceso de Armado y Ajuste de un Motor Diésel - Resultado de una Observación en la Comprobación del Estado y Funcionamiento Final del Motor utilizando Equipo de Diagnóstico de Motor. PRODUCTO 1. Un (1) Motor Diésel Reparado y Funcionando ', 14),
(8, 'DESEMPEÑO 1. Observación durante el proceso de operación de los recursos tecnológicos de la unidad administrativa. CONOCIMIENTO 1. Simulación de casos, análisis de casos y / o cuestionarios. PRODUCTO 1. Reporte de funcionamiento preventivo y/o correctivo de mantenimiento de los equipos de la unidad administrativa.', 17),
(9, 'DESEMPEÑO 1. Observación durante el uso del sistema operativo. CONOCIMIENTO 1. Cuestionario de conocimientos del elemento de competencia. PRODUCTO 1. Presentación electrónica multimedia almacenada en medio digital y virtual.', 18),
(10, 'DESEMPEÑO 1. Observación de tres momentos en la consulta del archivo. CONOCIMIENTO 1. Cuestionario y/o estudio de casos. PRODUCTO 1. Respuesta a tres solicitudes de información, por cualquier medio.', 22),
(12, 'DESEMPEÑO 1. Observación durante el proceso de despacho de cinco documentos. CONOCIMIENTO 1. Prueba escrita y/o estudio de casos. PRODUCTO 1. Registro de documentos despachados.', 20),
(14, 'DESEMPEÑO 1. Observación durante el proceso de recepción y registro de dos documentos físicos y dos documentos electrónicos. CONOCIMIENTO 1. Prueba escrita y/o estudio de casos PRODUCTO 1. Registro de recepción de documentos físicos o electrónicos', 21),
(15, 'DESEMPEÑO 1. Observación durante el proceso de recepción y registro de dos documentos físicos y dos documentos electrónicos. CONOCIMIENTO 1. Prueba escrita y/o estudio de casos. PRODUCTO 1. Registro de recepción de documentos físicos o electrónicos.', 19),
(16, 'DESEMPEÑO 1. Observación de la actitud de servicio frente a cinco clientes diferentes. CONOCIMIENTO 1. Cuestionario y/o análisis de casos. PRODUCTO 1. Cinco encuestas de satisfacción del servicio. 2. Un informe corto sobre los resultados de la evaluación de servicio.', 23),
(17, 'DESEMPEÑO 1. Observación durante la atención al cliente utilizando los medios de comunicación organizacionales. CONOCIMIENTO 1. Cuestionario y/o análisis de casos. PRODUCTO 1. Informe de trazabilidad del servicio de un cliente.', 24),
(19, 'DESEMPEÑO 1. Resultados de la observación durante el proceso de registro en los comprobantes y libros de contabilidad. 2. Estudio de casos. CONOCIMIENTO 1. Prueba escrita que abarque los conocimientos definidos para este elemento. PRODUCTO 1. Comprobantes y libros de contabilidad. ', 25),
(20, 'DESEMPEÑO 1. Resultados de la observación durante la elaboración de los estados financieros. 2. Estudio de casos. CONOCIMIENTO 1. Prueba escrita que abarque los conocimientos identificados para este elemento. PRODUCTO 1. Estados financieros clasificados.', 26),
(21, 'DESEMPEÑO 1. Resultado de la observación durante el análisis de los estados financieros. CONOCIMIENTO 1. Escrita sobre los conocimientos definidos en este elemento. PRODUCTO 1. Informe del análisis de los estados financieros.', 27),
(22, 'DESEMPEÑO 1. Observación directa de: mantenimiento de las condiciones de higiene y seguridad del espacio de trabajo 2. Cumplimiento de las normas de higiene y seguridad establecidas en la empresa y en el puesto de trabajo CONOCIMIENTO 1. Pruebas orales o escritas de: conocimientos y comprensiones de 1 hasta 7. PRODUCTO 1. Registro de las condiciones de higiene y seguridad del puesto de trabajo.', 28),
(23, 'DESEMPEÑO 1. Observación directa del trabajador en un procedimiento de: aplicación de disposiciones, normas y procedimientos de seguridad e higiene industrial y ambiental en el puesto de trabajo. CONOCIMIENTO 1. Pruebas orales y escritas sobre: conocimientos y comprensiones de 1 al 7 PRODUCTO 1. Registro de verificación de funcionamiento de maquinas, equipos o herramientas utilizados en su lugar de trabajo.', 30),
(25, 'DESEMPEÑO 1. Observación Directa De: Alistamiento De Dos Charlas De Sensibilización A La Población Trabajadora. CONOCIMIENTO 1. Prueba Oral O Escrita De Conocimientos Del 1 Al 9 PRODUCTO 1. Un Plan De Trabajo Ejecutado De Acuerdo Con Las Prioridades De Una Población Objeto. Presentación De Dos Ayudas Educativas Para El Proceso De Sensibilización', 31),
(26, 'DESEMPEÑO 1. Observación Directa De: Un Procedimiento De Identificación De La Población Objeto De Cobertura. Un Procedimiento De Informe De Resultados Obtenidos A La Persona Responsable De Salud Ocupacional Y Directivos De La Empresa. CONOCIMIENTO 1. Prueba Oral O Escrita De Conocimientos De 1 Al 4 PRODUCTO 1. Presentación De Estadísticas De Cumplimiento, De Cobertura Y De Cambios De Comportamiento De La Población Trabajadora (Formal E Informal).', 32),
(27, 'DESEMPEÑO 1. Interpretación, asociación de Pronósticos 2. Análisis de la gestión CONOCIMIENTO 1. Prueba Oral o escrita de : ?Tipificación de Amenazas, Características, dinámica de recurrencia, correlacionar referencias 2. Cartografía Básica PRODUCTO 1. Identificar y catalogar variables de la vulnerabilidad en el entorno social: Percepción conocimiento amenaza, capacidad de respuesta, recursos', 33),
(28, 'DESEMPEÑO 1. Frente a un caso argumentar las posibles intervenciones CONOCIMIENTO 1. Prueba oral y escrita sobre: ?Definir acciones que determinen amenaza y vulnerabilidad 2. En un cuadro relacione las acciones frente a las amenazas y vulnerabilidad PRODUCTO 1. Un proyecto de Intervención', 34),
(29, 'DESEMPEÑO 1. Observación Directa En: Un Caso Para Demostrar Capacidad Resolutiva De Planes En Corto Tiempo ? 30 Minutos CONOCIMIENTO 1. Prueba oral o escrita sobre: ?Vocabulario Técnico 2. Asociar estrategias de amenaza, afectación y procedimiento de respuesta por un evento determinado PRODUCTO 1. Elaborar plan de respuesta local argumentada dado un escenario de afectación y un panorama de amenazas', 35),
(30, 'DESEMPEÑO 1. Resultado De Dos (2) Observaciones De La EjecucióN Del Mantenimiento Preventivo CONOCIMIENTO 1. EvaluacióN Oral O Escrita Sobre: Procedimientos, Tecnicas Y Rutinas De Mantenimiento Preventivo. FuncióN De Los Sistemas Componentes De Los Automotores. - Lubricantes Y Refrigerantes.FuncióN De Los Sistemas Componentes De Los Automotores. - Lubricantes Y Refrigerantes.Tipos De Manuales De Fabricantes FuncióN De Componentes EléCtricos.Normas Ambientales, De Higiene Y Seguridad. PRODUCTO 1. Tres Reportes De Mantenimiento Preventivo Efectuado En Vehiculos , Liviano , Mediano Y Pesado.', 11),
(33, 'DESEMPEÑO 1. Una (1) ObservacióN En Los Proceso De VerificacióN De Los Componentes Del Sistema Del Sistema De Alimentacion E Inyectores De Combustible Diesel.Una (1) ObservacióN En El Manejo De Equipos E Instrumentos De DiagnóStico Del Sistema De AlimentacióN E Inyectores De Combustible Diesel.Una (1) ObservacióN En El Proceso De InterpretacióN De Resultados De Diagnostico CONOCIMIENTO 1. Respuesta A Preguntas Sobre:Procedimientos De EvaluacióN Y DiagnóStico Del Sistema De AlimentacióN E Inyectores De Combustible. CaracteríSticas Y FuncióN De Los Componentes Del Sistema De Alimentacion E Inyectores De Combustible. PRODUCTO 1. Un (1) Informe De DiagnóStico Del Sistema AlimentacióN E Inyectores De Combustible En Motores Diesel', 15),
(34, 'DESEMPEÑO 1. Una Observacion En La AplicacióN De Los Procesos De Reparacion De Los Sistemas De Alimentacion De Combustible-Dos (2) Observaciones Del Proceso De Evaluacion De Componentes Del Sistema De Alimentacion De Combustible-Una (1) ObservacióN Del Proceso De Calibrado De Inyectores-Una (1) ObservacióN De La ComprobacióN Del Estado Final De Funcionamiento Utilizando Equipos De Diagnostico CONOCIMIENTO 1. Respuesta A Preguntas Orales O Escritas ? CaracteríSticas Y FuncióN De Los Componentes Del Sistemas De AlimentacióN De Combustible. CaracteríSticas, Tipos Y FuncióN De Los Inyectores Procedimientos Y TéCnicas De ReparacióN De Los Sistemas De AlimentacióN De Combustible Normas De Seguridad Y Ambientales En La ManipulacióN De Combustibles Y Disolventes PRODUCTO 1. Un (1) Sistema De AlimentacióN De Combustible Diesel Reparado Con Su Respectivo Reporte Un Juego De Inyectores Librados SegúN ParáMetros Del Fabricante- Un Motor Puesto A Punto Y Funcionando , Con Su Informe Analizando Las Variables De OperacióN En Diferentes Regimes', 16),
(35, 'DESEMPEÑO 1. Observación respuesta a una comunicación dada. CONOCIMIENTO 1. Prueba escrita de conocimientos del elemento de competencia laboral. PRODUCTO 1. Redacción de una carta comercial y una circular general, de acuerdo con el rango de aplicación seleccionado.', 36),
(36, 'Conocimiento:   Prueba escrita sobre los temas vistos.  Desempeño:  Observación directa durante el proceso de verificación de las entradas y salidas de los objetos.  Producto:  Realizar reportes de verificación de entrada y salida de los objetos según procedimientos establecidos por la organización. ', 39),
(37, 'Conocimiento:   Prueba escrita sobre los temas vistos.  Desempeño:  Dos (2) observaciones del proceso de empaque de los objetos según técnicas o métodos y procedimientos establecidos.  Producto:  Entrega de los objetos empacados de acuerdo con la naturaleza y los procedimientos establecidos. ', 42),
(38, 'DESEMPEÑO 1. Movilización y transporte de heridos 2. Aplicar primeros auxilios por simulación en RCP, parto CONOCIMIENTO 1. Prueba Oral Y Escrita Sobre: Anatomía Y Fisiología Medidas De Bioseguridad Precauciones Generales De Un Accidente Medidas De Bioseguridad Y Técnica Aséptica Manejo De Intoxicación PRODUCTO 1. No Aplica.', 46),
(39, 'DESEMPEÑO 1. Observación directa de 2. Orientación a usuarios sobre servicios y horarios de una entidad de salud de su localidad ( 3 veces) CONOCIMIENTO 1. Prueba oral o escrita sobre: 2. Deberes y derechos en salud 3. Planes de beneficio que cubren las necesidades 4. Entidades IPS públicas y privadas de su localidad PRODUCTO 1. Mapa de la localidad con convenciones de las entidades de salud 2. Notificaciones obligatorias registradas en archivo con anterioridad de seis meses', 45),
(40, 'DESEMPEÑO Observación de la orientación para la atención en salud en dos actividades una individual y otra grupal CONOCIMIENTO Una (1) prueba oral o escrita para evidenciar conocimientos descritos en los numerales 1 al 7 PRODUCTO Un (1) registro donde se evidencie la orientación para el acceso a los diferentes servicios de salud', 47),
(41, 'DESEMPEÑO Observación directa durante el acompañamiento en la nutrición e higiene a tres niños o tres niñas en diferentes momentos de desarrollo CONOCIMIENTO Prueba oral y escrita para evaluar conocimientos comprendidos en los numerales 1 a 11 PRODUCTO Un (1) registro de un carné de vacunas verificado Un informe (1) de una ruta de gestión ante una situación riesgo', 48),
(42, 'DESEMPEÑO Observación directa durante la orientación en temas referentes a la promoción de la salud en niños niñas hasta los seis años. en dos momentos diferentes de acuerdo con los rangos de aplicación. CONOCIMIENTO Prueba oral y escrita para evaluar conocimientos descritos en los numerales del 1 al 18 PRODUCTO Un (1) material educativo para promover la lactancia materna. Un (1) mapa de riesgo de un ambiente educativo de niños y niñas hasta los seis años de edad.', 49),
(43, 'DESEMPEÑO Observación de la ejecución de las estrategias pedagógicas en las modalidades de atención y en los momentos del desarrollo, en dos actividades una individual y otra grupal CONOCIMIENTO Una (1) prueba oral o escrita para evidenciar conocimientos descritos en los numerales 1 al 10 PRODUCTO Un (1) registro donde se evidencie el diseño de las estrategias pedagógicas para el desarrollo integral de niños y niñas, sus familias y la comunidad', 50),
(44, 'DESEMPEÑO Tres (3) observaciones directas durante la realización de actividades lúdico pedagógicas en las tres modalidades de atención CONOCIMIENTO Prueba oral y escrita para evaluar conocimientos comprendidos en los numerales del 1 al 13 PRODUCTO Bitácora de las actividades realizadas con niños, niñas y sus familias realizadas en una semana en relación con promoción del desarrollo infantil', 51),
(45, 'DESEMPEÑO Observación directa de las actividades lúdico creativas utilizadas para la orientación y sensibilización a las niños niñas acerca de sus derechos y responsabilidades. CONOCIMIENTO Prueba oral o escrita acerca de los conceptos relacionados en los numerales del 1 al 13 PRODUCTO Una programación acerca de las estrategias utilizadas para la sensibilización de la familia acerca de los derechos y responsabilidades de los niños y niñas.', 52),
(46, 'DESEMPEÑO Observación directa de las actividades lúdico creativas utilizadas para la orientación y sensibilización a las niños niñas acerca de sus derechos y responsabilidades. CONOCIMIENTO Prueba oral o escrita acerca de los conceptos relacionados en los numerales del 1 al 13 PRODUCTO Una programación acerca de las estrategias utilizadas para la sensibilización de la familia acerca de los derechos y responsabilidades de los niños y niñas.', 53),
(47, 'DESEMPEÑO  Observación directa de una (1) actividad desarrollada con los niños y las niñas para evidenciar las estrategias de participación infantil empleadas. CONOCIMIENTO Una (1) prueba oral o escrita para evidenciar conocimientos descritos en los numerales 1 al 8. PRODUCTO Una (1) cartilla informativa acerca de la participación infantil, dirigida a los niños y las niñas Un (1) informe acerca de las acciones realizadas en una semana para el logro de la participación de niños y niñas', 54),
(48, 'DESEMPEÑO Observación directa de un (1) encuentro de motivación con una familia para la promoción de la participación infantil. CONOCIMIENTO Una (1) prueba oral o escrita para evidenciar conocimientos descritos en los numerales 1 al 10. PRODUCTO Diseño de una (1) estrategia para la difusión en la comunidad acerca de la importancia de la participación infantil en el desarrollo de los niños y las niñas.', 55),
(49, 'Estructuración de balance de prueba', 60),
(50, 'Preparación de balance de comprobación', 60),
