INSERT INTO `tbl_pqrs` (`ID_PQR`, `FECHA_PQR`, `USUARIO_PQR`, `VINCULACION_PQR`, `DESCRIPCION_PQR`, `TIPO_PQR`, `PROCESO_PQR`, `DEPENDENCIA_PQR`, `SERVICIO_PQR`, `RESPONSABLE_PQR`, `IMPORTANCIA_PQR`, `URGENCIA_PQR`, `DESCARGO_PQR`, `EVALUADO_PQR`, `FECHAEVALUACION_PQR`, `TRAMITE_PQR`, `FECHATRAMITE_PQR`) VALUES
(1, '2018-11-27', 5685, 'estudiante', 'El joven Anyello agredió de manera verbal, a la profesora KAtía Yajaira Verdeza, el alumno utiliza el chat grupal con palabras soeces, y llamando al teléfono de la docente para solicitar información en horas de la noche. la docente.', 'queja', 'Disciplinario', 'Coordinadora academica', 'atencion de quejas y reclamos', 'Coordinadora academica', 'alto', 'alto', 'La profesora Katía verdeza informa y presenta evidenciac del chat grupal, donde el alumno Anyello, la agrede de manera verbal utilizando un lenguaje vulgar y contesta inapropiadamente y grocero ,el alumno acepta su manera de comunicarse,', 'Coordinadora Academica', '2019-04-09', '1. Se procede inmediatamente a eschuchar la versión del alumno Anyello Gutierrez.\r\n2. Se solicita la impresión del Chat grupal donde esta tácitamente la agreción del alumno y la manera inapropiada de hacer el reclamo.\r\n3. Se solicitó la versión escrita de la profesora Katía Verdeza.\r\n\r\n4. Se realiza un llamado de atención verbal, atendiendo lo dispuesto en el caítulo VII, Del Reglamento Estudiantil Articulo 2 y Articulo  3.\r\n\r\nCierre de caso.', '2018-11-28'),
(2, '2019-04-29', 5881, 'estudiante', 'la Alumna hace solicitud de mantenimiento y reparación de los equipos de refrigerantes, y la implementación de ventiladores adicionales en la sala de informática, debido a que el calor de los equipos aumenta el calor generado, y esto afecta el rendimiento académico de los estudiantes.', 'reclamo', 'PROCESO', 'DEPENDENCIA', 'SERVICIO', 'Coordinadora Administratica', 'medio', 'medio', 'la Alumna hace solicitud de mantenimiento y reparación de los equipos de refrigerantes, y la implementación de ventiladores adicionales en la sala de informática, debido a que el calor de los equipos aumenta el calor generado, y esto afecta el rendimiento académico de los estudiantes.', NULL, NULL, 'Se realizó mantenimiento el día sábado 4 de mayo del 2019 a los aires acondicionados de la sala de computadores y se colocó otro ventilador de pared, para atender a la solicitud de la alumna', '2019-05-04'),
(14, '2019-06-11', 5683, 'estudiante', 'Sugerencia compra de atriles para sueros, para las prácticas de administración de medicamentos', 'percepcion', 'Solicitd', 'Gestión de Infraestructura y compra', 'sugerencia', 'Gestión de Infraestructura y compra', 'alto', 'alto', '', NULL, NULL, 'Se autoriza por parte del director la compra de tres atriles y biombos para prácticas de citologia, practicas de medicamentos parenterales.', '2019-06-14'),
(15, '2019-06-18', 3715, 'docente', 'solicita mantenimiento de aire acondicionado de aula 3.', 'sugerencia', 'gestión de infraestructura y compra', 'gestión de infraestructura y compra', 'swolicitud de mantenimiento', 'Lucila Fdez de C', 'medio', 'medio', '', NULL, NULL, 'Se programa para mitad de año epoca de vacaciones mantenimiento general de aires acondicionados. ', '2019-06-19'),
(16, '2019-08-26', 5864, 'estudiante', 'A mi se me perdió el cargador del Celular estando en la Sala de Procedimiento y yo me encontraba con (4) cuatro compañeras de clase y lo coloque a cargar y cuando lo fui a recoger no estaba de una  [el cargador]', 'percepcion', 'DISCIPLINARIO ', '', 'Atenci?n del reclamo ', '', 'medio', 'bajo', 'Yo Emeli relato los hechos:  una mañana estábamos de reposo en sala de procedimiento esperando que la seño Kelinet revisara los cuadernos para poder irnos, cuando pasaba ese momento yo decidí colocar a cargar mi celular ya que en esos momentos se encontraba en malas condiciones, el cel no se carga fácil, yo tenia dos  cargadores en la camilla con Loraine, Wendy y Victoria; cuando yo salia los tenia en la mano un original y el otro y cuando de la nada llego unas compañeras de clase y ella nos invitaron a una fiesta y una de ella cogio mi cargador y lo guardo en el bolso y esos momentos lo sacaba y lo metía y a la nada yo cogi mi bolso porque todo me pareció muy extraño, yo no trato con ella, así que de una dije voy a cargar mi celular y no encontré el cargador, de una fui donde ella y le pregunte, por esa va envista que ella fue la ultima que se acerco y tomo mi cargador, una de ellas se paro y me ayudo a buscarlo y le dije a la Seño que me ayudara, y ella me dijo que tranquila que eso tenia que aparecer mañana, y el dia de hoy no ha aparecido, y cuando estábamos llegando llego una de mis compañeras Landys Charris me comento que Maryuris Macias cogió mi cargador y se lo paso a Natali Zarate, y ella se lo dio a Yerson y la seño dice, bueno mañana hablamos eso y sino mañana lo paga todo el curso, y al dia siguiente no lo querían pagar, la alumna Maryuris Macia y Nataly Zarate, me pidieron que las revisara y lo hice y no tenían nada; también estaba Chelsy Gutierrez que fue la que acerco y nos contó todo estando la seño Kelinet presente.   \r\n\r\nYo Loraine Meza, no me acuerdo el dia que fue pero recuerdo que ese mismo dia se le perdio el cargador a mi amaiga Emely, que tenia en el bolso, las compañeras dicen  que vieron ha Nalaty Zarate, Maryuris Macias, Yerson, la verdad fue que no la vimos solo escuchamos, estamos en una corporacion para educarnos y es muy feo que algo se pierda entre nosotros mismos.\r\n\r\nWendy Meza, pues estábamos acostadas en la sala de procedimiento y se que lo tenia mi compañera Emely su cargador, soy testigo de eso, no las vi solo se que tenia dos cargadores, acostaba estábamos Victoria, Emely, Loraine y yo Wendy.\r\nChelsy Gutierrez, cuando me iba me acerque a un grupo de compañeras, la compañera Landys me dice que vio a Maryuris cuando le dio el cargador a Yerson y el se lo da a Nataly Zarate, y ella se lo lleva y yo me acerco a la profesora y le comento lo que estaba pasando, llega la compañera Landy y dice que ella fue la que los había visto a ellos llevarse el cargador.\r\n\r\nMaryuris Macias Acosta. El día 15 de agosto se perdió un cargador, yo ese día me acerque para comentarles a las hermanas Meza para salir, en ese momento yo vi los cargadores porque son dos, yo seguí hablando con ellas todo normal, entro al salón Yerson Garrido para pedir la contraseña de mi celular y seguimos hablando normal, yo sin embargo yo le metí el cargador en su bolso, me fui, ella llego al salón, ella me hace la pregunta le he dicho, pues yo le dije que se lo guarde, hasta yo misma le ayude a buscar, sin embargo antes de salir nos revisaron y no nos encontraron nada.  El 23 de agosto la compañera Daniela Lobelo me dijo que a mi era la que me estaban culpando del cargador !ya!\r\n\r\nNatalia Zarate Hernández, el 15 de agosto de 2019, se perdio un cargador soy acusada por algo queno me lleve, antes de salir del aula de clase le dije que me iba  que me podia requisar porque yo me iba, me revisó mi bolso y hasta la blusa me la alce para que se diera cuenta que yo no llevaba nada y me fui, desde ese dia me acusan de robo del cargador sin yo tenerlo, todo se dio en presencia de la seño.\r\n\r\nDaniela Lobelo, yo Daniela Lobelo D.I. escuche que una compañera la estaba acusando de robo de un cargador y yo se lo informe, y hoy 26 de agosto declaro lo que dije en presencia de todos lo que escuche. (la compañera acusada es MARYURIS MACIAS ACOSTA). \r\n\r\nYerson Garrido, Me culpan de haberme robado un cargador en el cual yo no estaba en el instante que se perdió el cargador.\r\n\r\n\r\n', NULL, NULL, '1. se escucharon a las diferentes partes para conocer a fondo la veracidad de la información suministrada.\r\n2. Se le hizo un llamado de atención a la docente y alumnos del programa de Auxiliar de Enfermería 2019 jornada Mañana por incumplimiento de las normas de la institución, donde las alumnas se esta prohibido estar cargando sus celulares en la institución a demás la sala de procedimientos solo el alumnado puede estar cuando se estén realizando procedimiento formativos, la sala de procedimiento no es una sala de descanso, no es sala de merienda, por su puesto no es sala de cargue de celulares, consiguiente a partir de la fecha la docente debe de ejercer mayor control con los celulares ya que esta herramienta solo debe ser sacada cuando tengan que investigar.\r\n\r\n3. se hace socialización con el curso y se le recuerda a la Docente Kelinet que cuando se están en el salón de clase los alumnos están a cargo de ella, por tal motivo deben de ejercer parámetros de disciplina y respecto por las pertenencias agenas, y que queda determinantemente prohibido colocar a cargar celulares en el aula de clase.', '2019-08-30'),
(17, '2019-08-27', 6010, 'estudiante', 'Yo Daniela Lobelo, tuve una discusión con el señor de la cafetería, porque no me atendió correctamente, me dio algo que no era, fue grosero delante de muchas personas.', 'percepcion', 'VIGILANCIA Y CONTRO ', '', 'SERVICIO AL CLIENTE ', 'COORDINACIÓN ACADÉMICA ', 'bajo', 'bajo', 'DANIELA LOBELO MALDONADO, identificada con cédula de ciudadanía No. 1221981312 de Ciénaga- Magdalena, me dirijo a usted señora Lucila muy respetuosamente, estableciendo mi inconformidad de la mala atención del señor de la cafetería Rafael Yepez, por tal motivo no deseo comprar en las instalaciones de la institución y pido muy agradecidamente que me conceda el permiso de salir en horas de receso a desayunar fuera de la institución. \r\n\r\nRAFAEL YEPEZ, soy el señor de la cafetería, discutí con la señorita DANIELA LOBELO, porque no cambie el producto comestible por otro, para no arriesgarme a que saliera equivocado; soy renuente a cambiar el producto cuan ha sido manipulado por el cliente, ya que es un producto comestible, siempre tengo buen trato con toda la población estudiantil. ', NULL, NULL, 'Lucila  Isabel Fernández de Castro Dangond, Coordinadora Académica, le concedo permiso para que la alumna DANIELA LOBELO pueda salir fuera de la institución a desayunar bajo su responsabilidad ya que la alumna Daniela me recalco que ella era mayor de edad y respondía por su seguridad. bajo este compromiso se le concede el permiso.', '2019-08-30'),
(18, '2023-05-25', 6776, 'estudiante', 'La joven solicita entrada al aula de clase porque en dicaha fecha vino sin el uniforme de enfemería. Por lo que el profesor Carlos solicito a la joven el permiso para entrar.', 'percepcion', 'Permiso  de entrada al aula', 'AULA 5', 'Recibir clases', 'Jhon Jader Bonet Cantillo', 'bajo', 'bajo', 'La joven se compromete a traer el uniforme al sigueinte dia de esta percepcion.', NULL, NULL, '', '2022-10-25'),
(19, '2023-05-26', 6717, 'estudiante', 'Añado solicitud de asistencia en el dia de 25 de mayo de 2023 de Naireth Orozco por problemas de salud. ', 'percepcion', 'No asistio a clases ', 'Aula de enfemeria', 'Clases ', 'Jhon Bonert Cantillo', 'bajo', 'bajo', '', NULL, NULL, '', '0000-00-00');
