INSERT INTO `tbl_rangos` (`ID_RANGO`, `NOMBRE_RANGO`, `ELEMENTO_RANGO`) VALUES
(1, 'COMPONENTES DE LA EXCAVADORA: - Motor y tren de potencia. - Tren de rodaje. - Bastidores. - Pluma y cucharón. SISTEMAS MECÁNICOS DE LA EXCAVADORA: - Sistema de traslación. - Sistema hidráulico y mecánico. - Sistema eléctrico. - Sistema de lubricación. CONTROLES DE LA EXCAVADORA: - Indicadores. - Alarmas. - Palancas y pedales.', 5),
(2, 'LABORES A EJECUTAR EN LA OPERACIÓN DE LA RETROEXCAVADORA: - Cargue de camiones en frentes. - Cargue de camiones en patios. - Apilamiento de material. - Excavadora o zanjas. - Conformación de vías o accesos y terraplenes. - Perfilado de talud. - Perfilado de piso. CONTROLES DE LA EXCAVADORA: - Indicadores. - Alarmas. - Palancas y pedales. FRENTES DE TRABAJO Y OPERACIÓN DE LA EXCAVADORA: - Frentes de trabajo y operación de la excavadora. ', 6),
